/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3text {	public static final class Attr {		public static final String align = "text-align";		public static final String vertical = "vertical-align";		public static final String decoration = "text-decoration";		public static final String transform = "text-transform";		public static final String lineHeight = "line-height";		public static final String letterSpacing = "letter-spacing";		public static final String wordSpacing = "word-spacing";		public static final String indent = "text-indent";		public static final String shadow = "text-shadow";		public static final String whiteSpace = "white-space";		public static final String overflow = "text-overflow";	}	public static final class X {		public static final String left = "left";		public static final String center = "center";		public static final String right = "right";		public static final String justify = "justify";	}	public static final class Y {		public static final String top = "top";		public static final String middle = "middle";		public static final String bottom = "bottom";	}	public static final class Decoration {		public static final String over = "overline";		public static final String through = "line-through";		public static final String under = "underline";		public static final String none = "none";	}	public static final class Transform {		public static final String uppercase = "uppercase";		public static final String lowercase = "lowercase";		public static final String capitalize = "capitalize";	}	public Value align(String x) {		return new Value().name(Attr.align).text(x);	}	public Value vertical(String y) {		return new Value().name(Attr.vertical).text(y);	}	public Value decoration(String decoration) {		return new Value().name(Attr.decoration).text(decoration);	}	public Value transform(String transform) {		return new Value().name(Attr.transform).text(transform);	}	public Value lineHeight(double ratio) {		ratio = (ratio > 0) ? ratio : 1.0;		return new Value().name(Attr.lineHeight).text(String.valueOf(ratio));	}	public Value lineHeight(String pixels) {		return new Value().name(Attr.lineHeight).text(pixels);	}	public Value letterSpacing(String pixels) {		return new Value().name(Attr.letterSpacing).text(pixels);	}	public Value wordSpacing(String pixels) {		return new Value().name(Attr.wordSpacing).text(pixels);	}	public Value indent(String pixels) {		return new Value().name(Attr.indent).text(pixels);	}	public Value shadow(String shorthand) {		return new Value().name(Attr.shadow).text(shorthand);	}	public Value whiteSpace(boolean wrap) {		String value = (wrap) ? "wrap" : "nowrap";		return new Value().name(Attr.whiteSpace).text(value);	}	public Value overflow(boolean clip) {		String value = (clip) ? "clip" : "ellipsis";		return new Value().name(Attr.overflow).text(value);	}}